package pe.edu.solucionesweb.tramite.controller;
import org.springframework.web.bind.annotation.*; import pe.edu.solucionesweb.tramite.model.EstadoTramite; import pe.edu.solucionesweb.tramite.repository.*; import java.util.*;
@RestController @RequestMapping("/api/reportes") @CrossOrigin(origins="http://localhost:4200") public class ReporteController { private final DocumentoRepository documentos;private final TramiteRepository tramites; public ReporteController(DocumentoRepository d,TramiteRepository t){documentos=d;tramites=t;} @GetMapping("/resumen") public Map<String,Object> resumen(){Map<String,Object> r=new LinkedHashMap<>();r.put("totalDocumentos",documentos.count());r.put("documentosPendientes",documentos.findAll().stream().filter(d->"PENDIENTE".equalsIgnoreCase(d.getEstado())).count());r.put("tramitesEnProceso",tramites.countByEstado(EstadoTramite.EN_PROCESO));r.put("tramitesConcluidos",tramites.countByEstado(EstadoTramite.CONCLUIDO));Map<String,Long> estados=new LinkedHashMap<>();for(EstadoTramite e:EstadoTramite.values())estados.put(e.name(),tramites.countByEstado(e));r.put("porEstado",estados);return r;} }
